import { Draw } from "ol/interaction";
import { Vector as VectorLayer } from "ol/layer";
import { Vector as VectorSource } from "ol/source";
import { Style, Stroke, Fill } from "ol/style";
import { getLength, getArea } from "ol/sphere";
import { LineString } from "ol/geom";
import Overlay from "ol/Overlay";

export class MeasureTool {
  constructor(map) {
    this.map = map;
    this.featureGroups = []; // 已完成的测量集合
    this.currentDraw = null;
    this.isDrawing = false;
    this.disabledInteractions = null; // 存储被暂时禁用的交互

    this.drawingLayer = null; // 当前未完成的图层
    this.drawingOverlays = []; // 当前未完成的覆盖物

    this.liveTipOverlay = this.createLiveTipOverlay();
    this.map.addOverlay(this.liveTipOverlay);

    this.map.on("pointermove", (evt) => {
      if (!evt.dragging && this.isDrawing) {
        this.liveTipOverlay.setPosition(evt.coordinate);
      }
    });

    // 点击地图外部结束绘制的事件处理函数
    this.handleOutsideClick = (event) => {
      if (this.isDrawing) {
        // 获取地图容器元素
        const mapElement = this.map.getTargetElement();
        
        // 检查点击目标是否在地图容器外部
        if (!mapElement.contains(event.target)) {
          // 立即结束绘制
          this.clearCurrentDrawing();
        }
      }
    };
  }

  createLiveTipOverlay() {
    const el = document.createElement("div");
    Object.assign(el.style, {
      position: "absolute",
      fontSize: "12px",
      color: "#666",
      background: "#fff",
      border: "1px solid #ccc",
      padding: "2px 4px",
      whiteSpace: "nowrap",
      zIndex: 999,
      pointerEvents: "none"
    });
    el.innerText = "单击确定起点";
    return new Overlay({
      element: el,
      offset: [8, 8],
      positioning: "bottom-left",
      stopEvent: false,
      position: undefined
    });
  }

  updateLiveTip(content) {
    this.liveTipOverlay.getElement().innerHTML = content;
  }

  createNodeOverlay(coord) {
    const node = document.createElement("div");
    Object.assign(node.style, {
      width: "10px",
      height: "10px",
      backgroundColor: "#fff",
      border: "2px solid red",
      borderRadius: "50%",
      position: "absolute",
      transform: "translate(-50%, -50%)",
      pointerEvents: "none"
    });
    return new Overlay({
      element: node,
      position: coord,
      positioning: "center-center",
      stopEvent: false
    });
  }

  createLabelOverlay(coord, text) {
    const label = document.createElement("div");
    Object.assign(label.style, {
      fontSize: "12px",
      fontWeight: "bold",
      color: "#7a7a7a",
      backgroundColor: "#fff",
      border: "1px solid #7a7a7a",
      padding: "2px 4px",
      borderRadius: "4px",
      opacity: 0.8,
      whiteSpace: "nowrap"
    });
    label.innerHTML = text;
    return new Overlay({
      element: label,
      position: coord,
      positioning: "bottom-center",
      offset: [0, -6],
      stopEvent: false
    });
  }

  formatLength(line) {
    const length = getLength(line, { projection: "EPSG:4326" });
    return length > 1000
      ? { value: (length / 1000).toFixed(2), unit: "km" }
      : { value: length.toFixed(2), unit: "m" };
  }

  formatArea(polygon) {
    const area = getArea(polygon, { projection: "EPSG:4326" });
    return area > 1000000
      ? { value: (area / 1000000).toFixed(2), unit: "km²" }
      : { value: area.toFixed(2), unit: "㎡" };
  }

  clearCurrentDrawing() {
    if (this.currentDraw) {
      this.map.removeInteraction(this.currentDraw);
      this.currentDraw = null;
    }

    if (this.drawingLayer) {
      this.map.removeLayer(this.drawingLayer);
      this.drawingLayer = null;
    }

    if (this.drawingOverlays.length > 0) {
      this.drawingOverlays.forEach((ov) => this.map.removeOverlay(ov));
      this.drawingOverlays = [];
    }

    // 恢复之前禁用的交互
    if (this.disabledInteractions && this.disabledInteractions.length > 0) {
      this.disabledInteractions.forEach(interaction => {
        // 检查interaction是否存在，避免undefined错误
        if (interaction) {
          this.map.addInteraction(interaction);
        }
      });
      this.disabledInteractions = null;
    }

    // 移除点击地图外部结束绘制的事件监听
    document.removeEventListener('mousedown', this.handleOutsideClick, true);

    this.isDrawing = false;
    this.updateLiveTip("");
    this.liveTipOverlay.setPosition(undefined);
  }

  start(type) {
    this.clearCurrentDrawing();
    this.isDrawing = true;
    this.updateLiveTip("单击确定起点");

    // 添加点击地图外部结束绘制的事件监听 - 使用mousedown和事件捕获模式提高可靠性
    document.addEventListener('mousedown', this.handleOutsideClick, true);

    // 暂时禁用可能干扰的交互（如Select和Modify）
    this.disabledInteractions = [];
    this.map.getInteractions().forEach(interaction => {
      // 检查interaction是否存在，避免undefined错误
      if (!interaction) return;
      
      // 检查交互类型名称，避免依赖导入的类
      const interactionType = interaction.constructor.name;
      if (interactionType === 'Select' || interactionType === 'Modify') {
        this.map.removeInteraction(interaction);
        this.disabledInteractions.push(interaction);
      }
    });

    const source = new VectorSource();
    const layer = new VectorLayer({
      source,
      style: new Style({
        stroke: new Stroke({ color: "#f00", width: 2 }),
        fill: new Fill({ color: "rgba(255,0,0,0.1)" })
      }),
      zIndex: 10
    });
    this.map.addLayer(layer);
    this.drawingLayer = layer;

    const draw = new Draw({
      source,
      type,
      style: new Style({
        stroke: new Stroke({ color: "#f00", width: 2 }),
        fill: new Fill({ color: "rgba(33,150,243,0.2)" })
      })
    });
    this.map.addInteraction(draw);
    this.currentDraw = draw;

    const overlays = this.drawingOverlays;

    draw.on("drawstart", (e) => {
      const geom = e.feature.getGeometry();
      let confirmedPoints = 0;

      geom.on("change", () => {
        const coords =
          type === "Polygon"
            ? geom.getCoordinates()[0].slice(0, -1)
            : geom.getCoordinates();

        if (coords.length > confirmedPoints) {
          const c = coords[coords.length - 1];

          // 只对LineString类型创建节点覆盖物，Polygon类型在drawend中创建
          if (type === "LineString") {
            const nodeOverlay = this.createNodeOverlay(c);
            this.map.addOverlay(nodeOverlay);
            overlays.push(nodeOverlay);
          }

          if (confirmedPoints === 0 && type === "LineString") {
            const label = this.createLabelOverlay(c, "起点");
            this.map.addOverlay(label);
            overlays.push(label);
          } else if (type === "LineString") {
            const line = new LineString(coords);
            const len = this.formatLength(line);
            const label = this.createLabelOverlay(
              c,
              `${len.value} ${len.unit}`
            );
            this.map.addOverlay(label);
            overlays.push(label);
          }

          confirmedPoints = coords.length;
        }

        if (type === "LineString" && coords.length > 1) {
          const line = new LineString(coords);
          const len = this.formatLength(line);
          this.updateLiveTip(
            `长度：${len.value} ${len.unit}<br/><span style="color:#999;">双击结束</span>`
          );
        } else {
          this.updateLiveTip("双击结束");
        }
      });
    });

    draw.on("drawend", (e) => {
      const feature = e.feature;
      const geom = feature.getGeometry();
      const coords =
        type === "Polygon"
          ? geom.getCoordinates()[0].slice(0, -1)
          : geom.getCoordinates();

      coords.forEach((c, i) => {
        // 只有多边形才需要在drawend事件中创建节点覆盖物
        // 线的节点覆盖物和标签已经在drawstart的geom.change事件中创建
        if (type === "Polygon") {
          const nodeOverlay = this.createNodeOverlay(c);
          this.map.addOverlay(nodeOverlay);
          overlays.push(nodeOverlay);
        }
      });

      if (type === "Polygon") {
        const area = this.formatArea(geom);
        const center = geom.getInteriorPoint().getCoordinates();
        const label = this.createLabelOverlay(
          center,
          `${area.value} ${area.unit}`
        );
        // 修改标签的定位，使其居中显示在图形上方
        label.setPositioning("center-center");
        label.setOffset([0, 0]);
        this.map.addOverlay(label);
        overlays.push(label);
      }

      const closeBtn = document.createElement("div");
      closeBtn.innerText = "✖";
      closeBtn.title = "清除";
      Object.assign(closeBtn.style, {
        color: "red",
        background: "#fff",
        border: "1px solid red",
        width: "14px",
        height: "14px",
        textAlign: "center",
        lineHeight: "12px",
        cursor: "pointer",
        fontSize: "12px",
        zIndex: 999
      });
      closeBtn.addEventListener("click", () => {
        this.map.removeLayer(layer);
        overlays.forEach((ov) => this.map.removeOverlay(ov));
        this.featureGroups = this.featureGroups.filter(
          (g) => g.feature !== feature
        );
      });

      const closeOverlay = new Overlay({
        element: closeBtn,
        positioning: "top-right",
        offset: [10, 10],
        stopEvent: false
      });
      closeOverlay.setPosition(coords[coords.length - 1]);
      this.map.addOverlay(closeOverlay);
      overlays.push(closeOverlay);

      // 正式保存为已完成
      this.featureGroups.push({
        feature,
        layer: this.drawingLayer,
        overlays: [...this.drawingOverlays]
      });

      // 重置
      this.map.removeInteraction(draw);
      this.currentDraw = null;
      this.isDrawing = false;
      this.drawingLayer = null;
      this.drawingOverlays = [];
      // 移除点击地图外部结束绘制的事件监听
      document.removeEventListener('mousedown', this.handleOutsideClick, true);
      this.updateLiveTip("");
      this.liveTipOverlay.setPosition(undefined);
    });
  }
}
